package awsreads

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"regexp"
	"strings"
	"time"
)

// Both sources are AWS's public documentation: no credentials, so the
// add-on can be regenerated by a scheduled job that holds none.
const (
	// ReadOnlyAccessPage publishes the policy document with its version.
	// Checked 2026-10-24: the same document IAM returns for v190.
	ReadOnlyAccessPage = "https://docs.aws.amazon.com/aws-managed-policy/latest/reference/ReadOnlyAccess.md"
	ServiceList        = "https://servicereference.us-east-1.amazonaws.com/v1/service-list.json"
)

var client = &http.Client{Timeout: 60 * time.Second}

func get(url string) ([]byte, error) {
	resp, err := client.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(io.LimitReader(resp.Body, 32<<20))
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("GET %s: HTTP %d", url, resp.StatusCode)
	}
	return b, nil
}

var (
	versionRE = regexp.MustCompile(`\*\*Policy version:\*\*\s*(v\d+)`)
	jsonRE    = regexp.MustCompile("(?s)## JSON policy document.*?```(?:json)?\\s*\\n(.*?)```")
)

// ParsePolicyPage reads the policy and its version from a managed policy's
// reference page. A page whose layout changed is an error, never an empty
// policy: that would make every read look missing.
func ParsePolicyPage(page []byte) (doc []byte, version string, err error) {
	v := versionRE.FindSubmatch(page)
	j := jsonRE.FindSubmatch(page)
	if v == nil || j == nil {
		return nil, "", fmt.Errorf("the page has no policy version or JSON document; its layout may have changed")
	}
	if !json.Valid(j[1]) {
		return nil, "", fmt.Errorf("the page's policy document is not valid JSON")
	}
	return j[1], string(v[1]), nil
}

// FetchReadOnlyAccess gets the current ReadOnlyAccess from AWS's page.
func FetchReadOnlyAccess() (doc []byte, version string, err error) {
	b, err := get(ReadOnlyAccessPage)
	if err != nil {
		return nil, "", err
	}
	return ParsePolicyPage(b)
}

// FetchReference gets the Service Reference for the services prefixes
// name. A service it does not have leaves that service's actions unknown;
// a fetch that fails is an error, so a network fault never reads as
// "AWS does not list these".
func FetchReference(prefixes []string) (*Reference, error) {
	b, err := get(ServiceList)
	if err != nil {
		return nil, err
	}
	var list []struct {
		Service string `json:"service"`
		URL     string `json:"url"`
	}
	if err := json.Unmarshal(b, &list); err != nil {
		return nil, fmt.Errorf("service list: %w", err)
	}
	if len(list) < 100 {
		return nil, fmt.Errorf("service list names only %d services; refusing a partial reference", len(list))
	}
	urls := map[string]string{}
	for _, s := range list {
		urls[s.Service] = s.URL
	}
	ref := &Reference{Actions: map[string]Flags{}, Names: map[string]string{}}
	for _, p := range prefixes {
		u, ok := urls[p]
		if !ok {
			continue
		}
		b, err := get(u)
		if err != nil {
			return nil, err
		}
		var svc struct {
			Actions []struct {
				Name        string `json:"Name"`
				Annotations struct {
					Properties Flags `json:"Properties"`
				} `json:"Annotations"`
			} `json:"Actions"`
		}
		if err := json.Unmarshal(b, &svc); err != nil {
			return nil, fmt.Errorf("%s: %w", p, err)
		}
		for _, a := range svc.Actions {
			k := strings.ToLower(p + ":" + a.Name)
			ref.Actions[k] = a.Annotations.Properties
			ref.Names[k] = p + ":" + a.Name
		}
	}
	return ref, nil
}

// Prefixes are the services the actions belong to.
func Prefixes(missing map[string][]string) []string {
	seen := map[string]bool{}
	var out []string
	for _, acts := range missing {
		for _, a := range acts {
			p, _, _ := strings.Cut(a, ":")
			if p = strings.ToLower(p); !seen[p] {
				seen[p] = true
				out = append(out, p)
			}
		}
	}
	return out
}
